INSERT INTO faqs (question, answer, sort_order) VALUES
  ('How much does delivery cost?', 'It depends on the distance, weight and speed. Use the Get a Quote form or WhatsApp us for a price.', 0),
  ('What can''t I send?', 'We don''t carry illegal, dangerous or prohibited items, cash or perishables without proper packaging. Ask if you''re unsure.', 1),
  ('Can you pick up from my location?', 'Yes. Book a pickup online or on WhatsApp.', 2),
  ('Do you offer business accounts?', 'Yes. Regular senders can get discounted rates and monthly billing. Contact us.', 3),
  ('What if my package is damaged?', 'Tell us immediately with photos. We''ll investigate and resolve it according to our terms.', 4);
